svg.script:
/**/
(function() {
  var dataStore = {
    "1": {
      title: "A14 · DIAGNÓSTICO DE GRAVIDEZ",
      status: "Status: Base Selada (Pilar Concluído)",
      faz: [
        "• Confirma a presunção, probabilidade e certeza.",
        "• Identifica BCF, movimentos fetais e Beta-hCG.",
        "• Define marcos ultrassônicos (SG 5s, VV 6s, BCF &gt;6s)."
      ],
      naofaz: [
        "• NÃO programa rotina de consultas continuadas.",
        "• NÃO avalia risco genético nem translucência nucal.",
        "• NÃO analisa adaptações fisiológicas sistêmicas."
      ],
      prova: [
        "• Diferença de prenhez clínica vs ultrassônica.",
        "• Duplicação esperada do Beta-hCG a cada 48h."
      ]
    },
    "2": {
      title: "A15 · MODIFICAÇÕES MATERNAS",
      status: "Status: Fisiologia Fundada (Pilar Concluído)",
      faz: [
        "• Fundamenta as adaptações cardiovasculares/renais.",
        "• Explica hemodiluição (Hb ≥ 11 g/dL é normal).",
        "• Justifica glicosúria fisiológica e ↑ VFG em 50%."
      ],
      naofaz: [
        "• NÃO faz triagem de infecções congênitas do pré-natal.",
        "• NÃO rastreia trissomias nem indica cariótipo.",
        "• NÃO prescreve suplementações do calendário de pré-natal."
      ],
      prova: [
        "• Fosfatase alcalina elevada é placentária (normal).",
        "• Alcalose respiratória compensada fisiológica."
      ]
    },
    "3": {
      title: "A16 · PRÉ-NATAL &amp; GENÉTICA",
      status: "Status: Nó Operacional Ativo (O Arco Fecha Aqui)",
      faz: [
        "• Opera o rastreamento longitudinal de riscos.",
        "• Triagem de aneuploidias (TN, NIPT, Ducto Venoso).",
        "• Indicação de exames invasivos (BVC / Amnio)."
      ],
      naofaz: [
        "• NÃO reabre confirmação de gestação (A14).",
        "• NÃO reensina adaptação fisiológica materna (A15).",
        "• NÃO detalha calendário/doses por semanas (H1)."
      ],
      prova: [
        "• TN ≥ 3,0mm ou DV 'a' reverso → Cariótipo Fetal.",
        "• BVC precoce (10-13s) vs Amniocentese (≥15s)."
      ]
    }
  };

  function updatePanel(nodeId) {
    var data = dataStore[nodeId];
    if (!data) return;

    // Highlight active node
    var nodes = document.querySelectorAll('.a16p1-node-group');
    nodes.forEach(function(n) {
      if (n.getAttribute('data-node') === nodeId) {
        n.classList.add('a16p1-active');
      } else {
        n.classList.remove('a16p1-active');
      }
    });

    // Update texts safely
    var tTitle = document.getElementById('a16p1-dyn-node-title');
    var tStatus = document.getElementById('a16p1-dyn-node-status');
    if (tTitle) tTitle.innerHTML = data.title;
    if (tStatus) tStatus.textContent = data.status;

    for (var i = 0; i < 3; i++) {
      var elFaz = document.getElementById('a16p1-dyn-faz-' + (i+1));
      var elNaoFaz = document.getElementById('a16p1-dyn-naofaz-' + (i+1));
      if (elFaz && data.faz[i]) elFaz.innerHTML = data.faz[i];
      if (elNaoFaz && data.naofaz[i]) elNaoFaz.innerHTML = data.naofaz[i];
    }

    for (var j = 0; j < 2; j++) {
      var elProva = document.getElementById('a16p1-dyn-prova-' + (j+1));
      if (elProva && data.prova[j]) elProva.innerHTML = data.prova[j];
    }
  }

  function init() {
    var nodes = document.querySelectorAll('.a16p1-node-group');
    nodes.forEach(function(node) {
      node.addEventListener('click', function() {
        var nodeId = this.getAttribute('data-node');
        updatePanel(nodeId);
      });

      node.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          var nodeId = this.getAttribute('data-node');
          updatePanel(nodeId);
        }
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
/**/
